// Life narrative — v1.4. A short, plain-language summary of the user's current
// state across the four domains, generated by Gemini. v1.22 (limecore#122):
// on the user's own key, straight from the device (lib/aiProvider); it used to
// go through the `ai-generate` function on the owner's key.
//
// Privacy: the prompt carries only aggregate 0–100 sub-scores and the
// already-on-screen pattern headlines — no transaction descriptions, amounts,
// account numbers, names, or other raw PII.
//
// A failure comes back as its reason (no key, invalid key, quota, model,
// network), so the card can say what the user can fix.

import { generate, type AiError } from './aiProvider';
import { type LifeProfile, type DomainKey } from './lifeProfile';
import { useSettingsStore } from '../store/useSettingsStore';

export interface NarrativeInput {
  /** Composite life score, 0–100. */
  lifeScore: number;
  /** Domain sub-scores, each 0–100. */
  workouts: number;
  study: number;
  habits: number;
  budget: number;
  /** v1.5 — Work domain sub-score, 0–100. Optional for back-compat. */
  work?: number;
  /** v1.5 — active Life Profile. When present, the prompt covers only the
   *  profile's enabled domains (so Professional talks about Work not Studies,
   *  Custom covers whatever's enabled). Absent → legacy 4-domain prompt. */
  profile?: LifeProfile;
  /** Headlines of the cross-domain patterns already surfaced on the Life tab. */
  insightHeadlines: string[];
}

function buildPrompt(input: NarrativeInput): string {
  const band = (n: number) =>
    n >= 75 ? 'strong' : n >= 50 ? 'steady' : n >= 25 ? 'slipping' : 'low';
  const patterns = input.insightHeadlines.length
    ? input.insightHeadlines.map((h) => `- ${h}`).join('\n')
    : '- (no notable cross-domain patterns this week)';

  // Build the domain lines from the active profile when present; otherwise
  // fall back to the legacy fixed four (Fitness/Studies/Habits/Budget).
  const LINES: Record<DomainKey, string> = {
    finance: `- Budget: ${band(input.budget)}`,
    fitness: `- Fitness: ${band(input.workouts)}`,
    studies: `- Studies: ${band(input.study)}`,
    work: `- Work: ${band(input.work ?? 0)}`,
    habits: `- Habits: ${band(input.habits)}`,
  };
  const order: DomainKey[] = ['finance', 'fitness', 'studies', 'work', 'habits'];
  const domainLines = input.profile
    ? order.filter((k) => input.profile!.domains[k] > 0).map((k) => LINES[k])
    : [LINES.fitness, LINES.studies, LINES.habits, LINES.finance];

  return `You are a personal life-dashboard assistant. Write 2–3 short sentences summarising this person's current week across life domains. Be specific, plain-language, and honest without being harsh or preachy. Do NOT mention numbers, scores, or percentages — translate them into concrete, human observations. Don't give a numbered list; write flowing prose. Don't invent facts beyond the data.

Domain standing this week (qualitative band in brackets):
${domainLines.join('\n')}

Patterns already detected:
${patterns}

Write the summary now:`;
}

/**
 * Generate the Life narrative on the user's own Gemini key. Returns the text,
 * or why it failed. Off (the switch) means no request at all.
 */
export async function generateLifeNarrative(input: NarrativeInput): Promise<{ text: string } | { error: AiError } | null> {
  // The opt-out gate, checked here rather than only at the call site: this is
  // the single point where anything leaves the device for Gemini, so a future
  // caller cannot bypass the user's choice by forgetting to check the flag.
  if (!useSettingsStore.getState().aiEnabled) return null;
  const res = await generate({ prompt: buildPrompt(input), maxTokens: 200, temperature: 0.6 });
  return res.ok ? { text: res.text } : { error: res.error };
}
